 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rays = []

    def add_ray(color, cells):
        valid = [(r, c) for r, c in cells if 0 <= r < h and 0 <= c < w]
        rays.append((color, valid))
        for r, c in valid:
            if out[r][c] == 0:
                out[r][c] = 5

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # Two steps right, then one step up to a second 1.
                cells = [(r, c), (r, c + 1), (r, c + 2), (r - 1, c + 2)]
                add_ray(1, cells)
                er, ec = r - 1, c + 2
                if 0 <= er < h and 0 <= ec < w:
                    out[er][ec] = 1
            elif color == 2:
                cells = [(r, c - d) for d in range(5)]
                add_ray(2, cells)
                er, ec = r, c - 4
                if 0 <= er < h and 0 <= ec < w:
                    out[er][ec] = 2
            elif color == 3:
                cells = [(r + d, c) for d in range(4)]
                add_ray(3, cells)
                er, ec = r + 3, c
                if 0 <= er < h and 0 <= ec < w:
                    out[er][ec] = 3
            elif color == 6:
                cells = [(r - d, c) for d in range(7)]
                add_ray(6, cells)
                er, ec = r - 6, c
                if 0 <= er < h and 0 <= ec < w:
                    out[er][ec] = 6

    # Crossings between different colored rays form a 4, which emits a
    # three-cell southwest diagonal.
    crossings = set()
    for i, (color_a, cells_a) in enumerate(rays):
        set_a = set(cells_a)
        for color_b, cells_b in rays[i + 1:]:
            if color_a != color_b:
                crossings.update(set_a.intersection(cells_b))
    for r, c in crossings:
        out[r][c] = 4
    for r, c in crossings:
        for d in range(1, 4):
            rr, cc = r + d, c - d
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = 4
    return out
